using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "WickedsCardOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/WickedsCardOmenData")]
public class WickedsCardOmenData : OnSpecificDiceTierOmenData
{
	[SerializeField]
	private OnStartOfBattleOmenData onStartOfBattleOmenData;

	[ShowNonSerializedField]
	private bool triggered;

	public override void Initialize(OmenInstance omenInstance)
	{
		triggered = false;
		base.Initialize(omenInstance);
		onStartOfBattleOmenData.Initialize(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.WickedsCardOmenAction = delegate(GameObject source, GameObject target)
		{
			if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && triggered)
			{
				OmenLogic.ActivateOmen(BattleAction, ActionValue, target, null);
			}
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction = delegate(GameObject source)
		{
			if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && triggered)
			{
				triggered = false;
			}
		};
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		onStartOfBattleOmenData.OmenRemoved();
		ReferenceSingleton<MiscOmensHandler>.Instance.WickedsCardOmenAction = null;
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return onStartOfBattleOmenData.GetOmenConvertedDescriptionBattleAction() + "\n" + base.OmenConvertedDescription();
	}

	protected override void OmenLogicActiveOmen(int actionAmount, GameObject target = null, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		triggered = true;
	}

	protected override string GetFirstPartAfterDicerTierPlayerLocalizedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), ActionValue, BattleAction.GetActionNameForDescription());
	}
}
